DROP TABLE IF EXISTS `WF_AGENT`;
CREATE TABLE WF_AGENT (
  ID VARCHAR(64 ) NOT NULL ,
  PROCESS_DEF_NAME VARCHAR(255 ) ,
  PROCESS_DEF_ID VARCHAR(64 ) ,
  TASK_DEF_KEY VARCHAR(200 ) ,
  START_DATE DATE ,
  END_DATE DATE ,
  AGENT_USER VARCHAR(64 ) ,
  TRUST_USER VARCHAR(64 ) ,
  TYPE VARCHAR(64 ) ,
  REMARKS VARCHAR(255 ) ,
  EFFECT_IND VARCHAR(255 ) ,
  TENANT_ID VARCHAR(64 ) ,
  CREATE_BY VARCHAR(64 ) ,
  AGENT_TYPE VARCHAR(20 ) ,
  CREATE_DATE DATE
);

ALTER TABLE WF_AGENT ADD PRIMARY KEY (ID);

ALTER TABLE WF_AGENT ADD TRUST_TYPE VARCHAR(10);

